import pdfMake from "pdfmake/build/pdfmake";
import { defineNuxtPlugin } from "#app";
import { cdnFonts, fontDescriptors, fontVfs, useDefaultRoboto } from "#build/pdfmake-fonts.mjs";
export default defineNuxtPlugin(async () => {
  if (Object.keys(fontVfs).length > 0) {
    pdfMake.addVirtualFileSystem(fontVfs);
  }
  if (useDefaultRoboto) {
    const vfsFontsModule = await import("pdfmake/build/vfs_fonts");
    const vfsData = vfsFontsModule.default ?? vfsFontsModule;
    pdfMake.addVirtualFileSystem(vfsData);
  }
  const allFonts = {
    ...fontDescriptors,
    ...cdnFonts
  };
  if (useDefaultRoboto) {
    allFonts.Roboto ??= {
      normal: "Roboto-Regular.ttf",
      bold: "Roboto-Medium.ttf",
      italics: "Roboto-Italic.ttf",
      bolditalics: "Roboto-MediumItalic.ttf"
    };
  }
  pdfMake.addFonts(allFonts);
  return {
    provide: { pdfMake }
  };
});
